package com.ridelink.drivervehicle.domain;
import java.time.Instant; import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.mapping.Document;
@Document("drivers") public class Driver { @Id private String id; private String userId, licenseNumber, serviceZone; private Vehicle vehicle; private Availability availability; private Double latitude, longitude; private Instant createdAt;
 public String getId(){return id;} public void setId(String v){id=v;} public String getUserId(){return userId;} public void setUserId(String v){userId=v;} public String getLicenseNumber(){return licenseNumber;} public void setLicenseNumber(String v){licenseNumber=v;} public String getServiceZone(){return serviceZone;} public void setServiceZone(String v){serviceZone=v;} public Vehicle getVehicle(){return vehicle;} public void setVehicle(Vehicle v){vehicle=v;} public Availability getAvailability(){return availability;} public void setAvailability(Availability v){availability=v;} public Double getLatitude(){return latitude;} public void setLatitude(Double v){latitude=v;} public Double getLongitude(){return longitude;} public void setLongitude(Double v){longitude=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;} }
